(6169220, 910382, 120976, '<td valign="top">B/W isn''t a bad idea, except his eye sockets are pure black, giving him an almost demonic expression! Didn''t quite fit the ''Pure Joy'' title.</td>', 'B/W isn''t a bad idea, except his eye sockets are pure black, giving him an almost demonic expression! Didn''t quite fit the ''Pure Joy'' title.', '2010-09-22 10:38:26.000000', NULL, 1),
(6169225, 910619, 120976, '<td valign="top">Fun idea! Might have been better without the piece of chair coming out of her forehead.</td>', 'Fun idea! Might have been better without the piece of chair coming out of her forehead.', '2010-09-22 10:39:54.000000', NULL, 1),
(6169227, 910762, 120976, '<td valign="top">I love this angle and brooding expression.</td>', 'I love this angle and brooding expression.', '2010-09-22 10:40:33.000000', NULL, 1),
(6169279, 910615, 39679, '<td valign="top">I really like the perspective you chose in this shot.</td>', 'I really like the perspective you chose in this shot.', '2010-09-22 11:22:34.000000', NULL, 1),
