(6171334, 910774, 117955, '<td valign="top">I just love this photo! From the detail in the floor, to her shoes, to her quirky outfit - and what a great expression on her face. Cool chair, also. Very nice.</td>', 'I just love this photo! From the detail in the floor, to her shoes, to her quirky outfit - and what a great expression on her face. Cool chair, also. Very nice.', '2010-09-24 22:05:09.000000', NULL, 1),
(6171335, 910666, 117955, '<td valign="top">Like this one a lot. Interesting lines of the chair, with him looking through... very nice.</td>', 'Like this one a lot. Interesting lines of the chair, with him looking through... very nice.', '2010-09-24 22:05:41.000000', NULL, 1),
(6171350, 910758, 121596, '<td valign="top">I like your style. Hope you win.</td>', 'I like your style. Hope you win.', '2010-09-24 22:29:22.000000', NULL, 1),
(6171443, 910405, 29079, '<td valign="top">so far the most original in this challenge I have seen..well done!! 10</td>', 'so far the most original in this challenge I have seen..well done!! 10', '2010-09-25 01:44:33.000000', NULL, 1),
(6171524, 910372, 121000, '<td valign="top">Love this, immediatley drawn straight through her eyes and into the story. Brilliant shot, Brilliant expression</td>', 'Love this, immediatley drawn straight through her eyes and into the story. Brilliant shot, Brilliant expression', '2010-09-25 09:06:28.000000', NULL, 1),
(6171525, 910391, 121000, '<td valign="top">Love the feel, Fantastic model, she really nails the expression. i feel sorry for her every time i look at this.</td>', 'Love the feel, Fantastic model, she really nails the expression. i feel sorry for her every time i look at this.', '2010-09-25 09:08:05.000000', NULL, 1),
(6171569, 910705, 10785, '<td valign="top">Very nice and dreamy effect created by the soft focus and wide open aperture. It conveys the message of the title well and gives a glimpse into the girls personality. I think of what can be improved and I would have to say that there is too much space above the head. The way you have her framed, it puts her face in the center of the photo and I would like to see it either in the top third using a portrait layout or in the left third using a landscape layout. Everything else is good... color, clarity, focus.</td>', 'Very nice and dreamy effect created by the soft focus and wide open aperture. It conveys the message of the title well and gives a glimpse into the girls personality. I think of what can be improved and I would have to say that there is too much space above the head. The way you have her framed, it puts her face in the center of the photo and I would like to see it either in the top third using a portrait layout or in the left third using a landscape layout. Everything else is good... color, clarity, focus.', '2010-09-25 11:19:20.000000', NULL, 1),
(6171572, 910703, 10785, '<td valign="top">I like this portrait. It tells the story of the man very well. I just question why you have framed the man with him in the left third here.</td>', 'I like this portrait. It tells the story of the man very well. I just question why you have framed the man with him in the left third here.', '2010-09-25 11:28:06.000000', NULL, 1),
(6171573, 910672, 10785, '<td valign="top">Ghostly!!! I get a spanish or mexican vibe off this because I see the face of Jesus in the misty blur... (Bottom left above the chair!!)</td>', 'Ghostly!!! I get a spanish or mexican vibe off this because I see the face of Jesus in the misty blur... (Bottom left above the chair!!)', '2010-09-25 11:29:40.000000', NULL, 1),
(6171574, 910211, 10785, '<td valign="top">The handbag, the serious face, the legs crossed... they all serve to tell the story of who she is! The image is very good... crisp, clear , great tones, well composed!</td>', 'The handbag, the serious face, the legs crossed... they all serve to tell the story of who she is! The image is very good... crisp, clear , great tones, well composed!', '2010-09-25 11:35:33.000000', NULL, 1),
