(6174267, 910402, 96751, '<td valign="top">Congrats on your HM!  Beautiful image.  Love that I think it has too much contrast and <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=47470" rel="nofollow" target="_blank">geinafets</a> thinks it needs more!</td>', 'Congrats on your HM!  Beautiful image.  Love that I think it has too much contrast and  geinafets thinks it needs more!', '2010-09-29 03:09:45.000000', NULL, 0),
(6174268, 910698, 96751, '<td valign="top">Ah, sir, you LIVE on the front page.  Congrats on yet another stellar capture.</td>', 'Ah, sir, you LIVE on the front page.  Congrats on yet another stellar capture.', '2010-09-29 03:11:46.000000', NULL, 0),
(6174269, 910770, 108990, '<td valign="top">Thanks for the nice comments everyone! ^_^ It''s kind of scary putting on a self portrait, but I like the comment ''a woman of tranquil force''...I plan to refer to myself as that from now on!! Thanks :D</td>', 'Thanks for the nice comments everyone! ^_^ It''s kind of scary putting on a self portrait, but I like the comment ''a woman of tranquil force''...I plan to refer to myself as that from now on!! Thanks :D', '2010-09-29 03:12:39.000000', NULL, 0);
