(6174323, 910405, 58715, '<td valign="top">Hey guys beware.. Judi is back on board.. :)It is nice to see you back with bang.. <br/> <br/>Congratulations and welcome back.</td>', 'Hey guys beware.. Judi is back on board.. :)It is nice to see you back with bang..  Congratulations and welcome back.', '2010-09-29 03:58:48.000000', NULL, 0),
