(6174462, 910774, 53147, '<td valign="top">Wow - I expected this to place much much higher. It was high on my vote.</td>', 'Wow - I expected this to place much much higher. It was high on my vote.', '2010-09-29 07:44:27.000000', NULL, 0),
(6174467, 909974, 98771, '<td valign="top">Just an excellent image, very creative and well done. Congratulations, you are on a roll..</td>', 'Just an excellent image, very creative and well done. Congratulations, you are on a roll..', '2010-09-29 07:50:14.000000', NULL, 0),
(6174469, 910211, 98771, '<td valign="top">Congratulations!!</td>', 'Congratulations!!', '2010-09-29 07:51:01.000000', NULL, 0),
(6174487, 910405, 30861, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Judi:</b></div><hr/><i> <table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Bear_Music:</b></div><hr/><i> Holy CHIT! She comes back hotter than ever! WTG! </i></td></tr></table> <br/>Hehehe yu are funny.  I know that my style has changed, I am editing with a different result now.  I am not sure if I like it yet, but I suppose I have to get used to it.  My OT had a good talk with me the other day and said that I will never return to what I was but I will find ways around it.  And I guess I am, in this case, my editing style. </i></td></tr></table> <br/> <br/>That''s absolutely correct, and I''m pleased you noticed it about yourself. This is a very different sort of aesthetic than your "normal" style from the old days, pre-accident. Personally, I think it''s a step forward, but then I would, wouldn''t I? :-)</td>', 'Originally posted by Judi: Originally posted by Bear_Music: Holy CHIT! She comes back hotter than ever! WTG!  Hehehe yu are funny.  I know that my style has changed, I am editing with a different result now.  I am not sure if I like it yet, but I suppose I have to get used to it.  My OT had a good talk with me the other day and said that I will never return to what I was but I will find ways around it.  And I guess I am, in this case, my editing style.   That''s absolutely correct, and I''m pleased you noticed it about yourself. This is a very different sort of aesthetic than your "normal" style from the old days, pre-accident. Personally, I think it''s a step forward, but then I would, wouldn''t I? :-)', '2010-09-29 08:17:58.000000', NULL, 0),
(6174517, 910405, 113278, '<td valign="top">Not only do you come back with the blue but you also have a new top 5 image on your profile page. Big congrats to you :)</td>', 'Not only do you come back with the blue but you also have a new top 5 image on your profile page. Big congrats to you :)', '2010-09-29 09:00:13.000000', NULL, 0),
(6174521, 910738, 81530, '<td valign="top">Great shot Jac.</td>', 'Great shot Jac.', '2010-09-29 09:17:03.000000', NULL, 0),
